-- DropKilat initial schema. PostgreSQL 17.
-- Money: BIGINT rupiah. Time: timestamptz (UTC). IDs: uuid (UUIDv7 generated by the app; default is a fallback).
-- PII (phones, addresses, bank accounts) is encrypted by the app (AES-256-GCM) and stored as bytea;
-- *_hash columns are HMAC-SHA256 for lookups.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- Helper for RLS: current seller from the transaction setting, NULL if unset.
CREATE FUNCTION app_seller_id() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('app.seller_id', true), '')::uuid
$$;

CREATE FUNCTION app_is_system() RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT COALESCE(current_setting('app.role', true), '') IN ('system', 'public')
$$;

-- ---------------------------------------------------------------- sellers

CREATE TABLE sellers (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shop_name              text NOT NULL CHECK (char_length(shop_name) BETWEEN 2 AND 60),
  slug                   text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'),
  phone_enc              bytea NOT NULL,
  phone_hash             bytea NOT NULL UNIQUE,
  timezone               text NOT NULL DEFAULT 'Asia/Jakarta',
  status                 text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
  phone_verified_at      timestamptz,
  identity_verified_at   timestamptz,
  social_linked_at       timestamptz,
  xendit_subaccount_id   text UNIQUE,
  xendit_kyc_status      text CHECK (xendit_kyc_status IN ('pending', 'verified', 'rejected')),
  manual_qris_path       text,
  manual_bank_name       text,
  manual_account_enc     bytea,
  manual_account_name    text,
  limited_until_trusted  boolean NOT NULL DEFAULT true,
  created_at             timestamptz NOT NULL DEFAULT now(),
  updated_at             timestamptz NOT NULL DEFAULT now()
);
CREATE TRIGGER sellers_updated_at BEFORE UPDATE ON sellers FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE seller_sessions (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  seller_id     uuid NOT NULL REFERENCES sellers(id) ON DELETE CASCADE,
  token_hash    bytea NOT NULL UNIQUE,
  user_agent    text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  last_seen_at  timestamptz NOT NULL DEFAULT now(),
  expires_at    timestamptz NOT NULL
);
CREATE INDEX seller_sessions_seller_idx ON seller_sessions (seller_id);

CREATE TABLE otp_challenges (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  purpose      text NOT NULL CHECK (purpose IN ('seller_login', 'buyer_verify')),
  phone_hash   bytea NOT NULL,
  code_hash    bytea NOT NULL,
  attempts     smallint NOT NULL DEFAULT 0 CHECK (attempts <= 5),
  expires_at   timestamptz NOT NULL,
  consumed_at  timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX otp_challenges_phone_idx ON otp_challenges (phone_hash, created_at DESC);

CREATE TABLE seller_social_links (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  seller_id    uuid NOT NULL REFERENCES sellers(id) ON DELETE CASCADE,
  platform     text NOT NULL CHECK (platform IN ('instagram', 'tiktok')),
  handle       text NOT NULL CHECK (handle ~ '^[A-Za-z0-9._]{1,30}$'),
  verify_code  text NOT NULL,
  status       text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'rejected')),
  verified_at  timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (platform, handle)
);
CREATE INDEX seller_social_links_seller_idx ON seller_social_links (seller_id);

CREATE TABLE seller_stats (
  seller_id         uuid PRIMARY KEY REFERENCES sellers(id) ON DELETE CASCADE,
  drops_completed   integer NOT NULL DEFAULT 0,
  orders_paid       integer NOT NULL DEFAULT 0,
  orders_received   integer NOT NULL DEFAULT 0,
  orders_reported   integer NOT NULL DEFAULT 0,
  updated_at        timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------- drops

CREATE TABLE drops (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  seller_id      uuid NOT NULL REFERENCES sellers(id),
  slug           text NOT NULL CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,58}[a-z0-9]$'),
  title          text NOT NULL CHECK (char_length(title) BETWEEN 3 AND 100),
  description    text NOT NULL DEFAULT '' CHECK (char_length(description) <= 2000),
  status         text NOT NULL DEFAULT 'draft'
                 CHECK (status IN ('draft', 'scheduled', 'live', 'closed', 'cancelled')),
  opens_at       timestamptz NOT NULL,
  closes_at      timestamptz NOT NULL,
  hold_minutes   smallint NOT NULL DEFAULT 15 CHECK (hold_minutes BETWEEN 5 AND 30),
  grace_seconds  smallint NOT NULL DEFAULT 120 CHECK (grace_seconds BETWEEN 0 AND 600),
  max_per_buyer  smallint NOT NULL DEFAULT 1 CHECK (max_per_buyer BETWEEN 1 AND 10),
  payment_mode   text NOT NULL DEFAULT 'manual' CHECK (payment_mode IN ('manual', 'xendit')),
  closed_reason  text,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  UNIQUE (seller_id, slug),
  CHECK (closes_at > opens_at)
);
CREATE INDEX drops_schedule_idx ON drops (status, opens_at) WHERE status IN ('scheduled', 'live');
CREATE TRIGGER drops_updated_at BEFORE UPDATE ON drops FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE drop_photos (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  drop_id    uuid NOT NULL REFERENCES drops(id) ON DELETE CASCADE,
  seller_id  uuid NOT NULL REFERENCES sellers(id),
  path       text NOT NULL,
  position   smallint NOT NULL DEFAULT 0
);
CREATE INDEX drop_photos_drop_idx ON drop_photos (drop_id, position);

CREATE TABLE drop_variants (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  drop_id      uuid NOT NULL REFERENCES drops(id) ON DELETE CASCADE,
  seller_id    uuid NOT NULL REFERENCES sellers(id),
  name         text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 60),
  price        bigint NOT NULL CHECK (price BETWEEN 1000 AND 100000000),
  stock_total  integer NOT NULL CHECK (stock_total BETWEEN 1 AND 10000),
  available    integer NOT NULL,
  position     smallint NOT NULL DEFAULT 0,
  CHECK (available >= 0 AND available <= stock_total),
  UNIQUE (drop_id, name)
);
CREATE INDEX drop_variants_drop_idx ON drop_variants (drop_id, position);

-- ---------------------------------------------------------------- buyers

CREATE TABLE buyers (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  phone_enc     bytea NOT NULL,
  phone_hash    bytea NOT NULL UNIQUE,
  display_name  text,
  verified_at   timestamptz NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE buyer_sessions (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  buyer_id    uuid NOT NULL REFERENCES buyers(id) ON DELETE CASCADE,
  token_hash  bytea NOT NULL UNIQUE,
  created_at  timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz NOT NULL
);
CREATE INDEX buyer_sessions_buyer_idx ON buyer_sessions (buyer_id);

-- Buyer-initiated WhatsApp verification: the page holds a nonce, the buyer sends `code` from WA.
CREATE TABLE buyer_verifications (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code          text NOT NULL UNIQUE CHECK (code ~ '^DK-[A-Z0-9]{4,8}$'),
  nonce_hash    bytea NOT NULL UNIQUE,
  status        text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'expired')),
  buyer_id      uuid REFERENCES buyers(id),
  expires_at    timestamptz NOT NULL,
  verified_at   timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX buyer_verifications_pending_idx ON buyer_verifications (expires_at) WHERE status = 'pending';

-- ---------------------------------------------------------------- orders

CREATE TABLE orders (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code                 text NOT NULL UNIQUE CHECK (code ~ '^[A-Z0-9]{8}$'),
  seller_id            uuid NOT NULL REFERENCES sellers(id),
  drop_id              uuid NOT NULL REFERENCES drops(id),
  variant_id           uuid NOT NULL REFERENCES drop_variants(id),
  buyer_id             uuid NOT NULL REFERENCES buyers(id),
  qty                  smallint NOT NULL CHECK (qty BETWEEN 1 AND 10),
  unit_price           bigint NOT NULL CHECK (unit_price > 0),
  amount               bigint NOT NULL CHECK (amount = unit_price * qty),
  payment_mode         text NOT NULL CHECK (payment_mode IN ('manual', 'xendit')),
  source               text NOT NULL DEFAULT 'claim' CHECK (source IN ('claim', 'waitlist')),
  status               text NOT NULL CHECK (status IN (
                         'held', 'proof_submitted', 'paid', 'expired', 'cancelled', 'rejected',
                         'shipped', 'completed', 'disputed', 'refund_pending', 'refunded')),
  hold_expires_at      timestamptz,
  proof_path           text,
  proof_submitted_at   timestamptz,
  reject_reason        text,
  paid_at              timestamptz,
  recipient_name       text,
  recipient_phone_enc  bytea,
  address_enc          bytea,
  postal_code          text CHECK (postal_code ~ '^[0-9]{5}$'),
  courier              text,
  tracking_number      text,
  shipped_at           timestamptz,
  completed_at         timestamptz,
  ended_at             timestamptz,   -- expired/cancelled/rejected/refunded time
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CHECK (status <> 'held' OR hold_expires_at IS NOT NULL)
);
-- Expiry worker scan.
CREATE INDEX orders_hold_expiry_idx ON orders (hold_expires_at) WHERE status = 'held';
-- Max-per-buyer check and "my orders in this drop".
CREATE INDEX orders_drop_buyer_active_idx ON orders (drop_id, buyer_id)
  WHERE status IN ('held', 'proof_submitted', 'paid', 'shipped', 'completed', 'disputed');
CREATE INDEX orders_seller_status_idx ON orders (seller_id, status, created_at DESC);
CREATE INDEX orders_buyer_idx ON orders (buyer_id, created_at DESC);
CREATE TRIGGER orders_updated_at BEFORE UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE waitlist_entries (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  seller_id   uuid NOT NULL REFERENCES sellers(id),
  drop_id     uuid NOT NULL REFERENCES drops(id),
  variant_id  uuid NOT NULL REFERENCES drop_variants(id),
  buyer_id    uuid NOT NULL REFERENCES buyers(id),
  qty         smallint NOT NULL DEFAULT 1 CHECK (qty BETWEEN 1 AND 10),
  status      text NOT NULL DEFAULT 'waiting'
              CHECK (status IN ('waiting', 'offered', 'skipped', 'left', 'closed')),
  order_id    uuid REFERENCES orders(id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  offered_at  timestamptz,
  CHECK (status <> 'offered' OR order_id IS NOT NULL)
);
CREATE UNIQUE INDEX waitlist_one_waiting_per_buyer ON waitlist_entries (variant_id, buyer_id) WHERE status = 'waiting';
CREATE INDEX waitlist_fifo_idx ON waitlist_entries (variant_id, created_at, id) WHERE status = 'waiting';

-- ---------------------------------------------------------------- payments

CREATE TABLE payments (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id       uuid NOT NULL REFERENCES orders(id),
  seller_id      uuid NOT NULL REFERENCES sellers(id),
  provider       text NOT NULL CHECK (provider IN ('manual', 'xendit', 'fake')),
  provider_ref   text,
  amount         bigint NOT NULL CHECK (amount > 0),
  pg_fee         bigint NOT NULL DEFAULT 0 CHECK (pg_fee >= 0),
  platform_fee   bigint NOT NULL DEFAULT 0 CHECK (platform_fee >= 0),
  status         text NOT NULL CHECK (status IN ('pending', 'paid', 'expired', 'failed', 'refund_pending', 'refunded')),
  qr_string      text,
  expires_at     timestamptz,
  paid_at        timestamptz,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  UNIQUE (provider, provider_ref)
);
CREATE INDEX payments_order_idx ON payments (order_id);
CREATE TRIGGER payments_updated_at BEFORE UPDATE ON payments FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Every inbound webhook lands here first. Unique event id = idempotency.
CREATE TABLE webhook_events (
  id            bigserial PRIMARY KEY,
  provider      text NOT NULL CHECK (provider IN ('xendit', 'whatsapp')),
  event_id      text NOT NULL,
  event_type    text NOT NULL,
  payload       jsonb NOT NULL,
  received_at   timestamptz NOT NULL DEFAULT now(),
  processed_at  timestamptz,
  result        text,
  UNIQUE (provider, event_id)
);
CREATE INDEX webhook_events_unprocessed_idx ON webhook_events (received_at) WHERE processed_at IS NULL;

-- ---------------------------------------------------------------- side effects, trust, audit

CREATE TABLE outbox (
  id          bigserial PRIMARY KEY,
  kind        text NOT NULL,                 -- e.g. wa.payment_link, wa.waitlist_turn, wa.paid
  dedupe_key  text UNIQUE,                   -- e.g. order:<id>:payment_link
  payload     jsonb NOT NULL,
  send_after  timestamptz NOT NULL DEFAULT now(),
  attempts    smallint NOT NULL DEFAULT 0,
  last_error  text,
  sent_at     timestamptz,
  dead_at     timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX outbox_due_idx ON outbox (send_after) WHERE sent_at IS NULL AND dead_at IS NULL;

CREATE TABLE reports (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  seller_id   uuid NOT NULL REFERENCES sellers(id),
  order_id    uuid REFERENCES orders(id),
  buyer_id    uuid REFERENCES buyers(id),
  kind        text NOT NULL CHECK (kind IN ('not_received', 'fake_account', 'wrong_item', 'other')),
  message     text NOT NULL CHECK (char_length(message) BETWEEN 5 AND 2000),
  status      text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'rejected')),
  resolution  text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  resolved_at timestamptz
);
CREATE INDEX reports_seller_idx ON reports (seller_id, status);

CREATE TABLE audit_log (
  id          bigserial PRIMARY KEY,
  seller_id   uuid,
  actor_type  text NOT NULL CHECK (actor_type IN ('seller', 'buyer', 'system', 'owner')),
  actor_id    text,
  action      text NOT NULL,                 -- e.g. order.confirm, order.reject, drop.close, seller.verify
  entity      text NOT NULL,
  entity_id   text NOT NULL,
  data        jsonb NOT NULL DEFAULT '{}',
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_entity_idx ON audit_log (entity, entity_id);

-- ---------------------------------------------------------------- row level security
-- The app connects as role `dropkilat_app` (not the table owner). Each transaction sets
--   SET LOCAL app.seller_id = '<uuid>'   for seller-scoped requests, or
--   SET LOCAL app.role = 'system'        for workers and webhook processing, or
--   SET LOCAL app.role = 'public'        for buyer-facing reads.
-- RLS is the second line of defence; queries must still filter by seller_id.

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['drops', 'drop_photos', 'drop_variants', 'orders', 'waitlist_entries',
                           'payments', 'seller_social_links', 'reports']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I USING (app_is_system() OR seller_id = app_seller_id()) '
      'WITH CHECK (app_is_system() OR seller_id = app_seller_id())', t || '_tenant', t);
  END LOOP;
END $$;

-- Grants for the app role (created by deploy/init-db.sql). audit_log is append-only for it.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dropkilat_app') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO dropkilat_app;
    GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO dropkilat_app;
    REVOKE UPDATE, DELETE, TRUNCATE ON audit_log FROM dropkilat_app;
  END IF;
END $$;

COMMIT;
